-- Original 15 table names are retained; additional normalized tables implement required accounting and security.
CREATE TABLE department (id BIGINT AUTO_INCREMENT PRIMARY KEY, dept_code VARCHAR(32) NOT NULL UNIQUE, dept_name VARCHAR(80) NOT NULL, dept_type VARCHAR(40) NOT NULL DEFAULT '门诊', delmark TINYINT NOT NULL DEFAULT 1);
CREATE TABLE regist_level (id BIGINT AUTO_INCREMENT PRIMARY KEY, regist_code VARCHAR(32) NOT NULL UNIQUE, regist_name VARCHAR(50) NOT NULL, regist_fee DECIMAL(10,2) NOT NULL, regist_quota INT NOT NULL, sequence_no INT NOT NULL DEFAULT 1, delmark TINYINT NOT NULL DEFAULT 1);
CREATE TABLE settle_category (id BIGINT AUTO_INCREMENT PRIMARY KEY, settle_code VARCHAR(32) NOT NULL UNIQUE, settle_name VARCHAR(60) NOT NULL, sequence_no INT NOT NULL DEFAULT 1, delmark TINYINT NOT NULL DEFAULT 1);
CREATE TABLE employee (id BIGINT AUTO_INCREMENT PRIMARY KEY, deptment_id BIGINT NULL, regist_level_id BIGINT NULL, realname VARCHAR(80) NOT NULL, username VARCHAR(64) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, role VARCHAR(24) NOT NULL, delmark TINYINT NOT NULL DEFAULT 1, CONSTRAINT fk_employee_dept FOREIGN KEY (deptment_id) REFERENCES department(id));
CREATE TABLE scheduling (id BIGINT AUTO_INCREMENT PRIMARY KEY, employee_id BIGINT NOT NULL, week_rule INT NOT NULL, noon VARCHAR(8) NOT NULL, quota INT NOT NULL, delmark TINYINT NOT NULL DEFAULT 1, CONSTRAINT fk_schedule_emp FOREIGN KEY (employee_id) REFERENCES employee(id), UNIQUE KEY uk_schedule(employee_id,week_rule,noon));
CREATE TABLE patient (id BIGINT AUTO_INCREMENT PRIMARY KEY, case_number VARCHAR(32) UNIQUE, client_request_id VARCHAR(80) UNIQUE, real_name VARCHAR(80) NOT NULL, gender VARCHAR(8) NOT NULL, card_number VARCHAR(255), card_hash CHAR(64) UNIQUE, birthdate DATE, home_address VARCHAR(255), phone VARCHAR(32), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE register (id BIGINT AUTO_INCREMENT PRIMARY KEY, patient_id BIGINT NOT NULL, client_request_id VARCHAR(80) UNIQUE, employee_id BIGINT NOT NULL, deptment_id BIGINT NOT NULL, regist_level_id BIGINT NOT NULL, settle_category_id BIGINT NOT NULL, visit_date DATE NOT NULL, noon VARCHAR(8) NOT NULL, is_book TINYINT NOT NULL DEFAULT 0, regist_money DECIMAL(10,2) NOT NULL, visit_state VARCHAR(24) NOT NULL DEFAULT 'WAITING', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_reg_patient FOREIGN KEY(patient_id) REFERENCES patient(id), CONSTRAINT fk_reg_emp FOREIGN KEY(employee_id) REFERENCES employee(id), INDEX idx_reg_visit(employee_id,visit_date,noon,visit_state));
CREATE TABLE medical_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, register_id BIGINT NOT NULL UNIQUE, chief_complaint TEXT, present_illness TEXT, treatment_history TEXT, past_history TEXT, allergies TEXT, physical_exam TEXT, preliminary_diagnosis TEXT, suggestions TEXT, final_diagnosis TEXT, treatment_plan TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_record_reg FOREIGN KEY(register_id) REFERENCES register(id));
CREATE TABLE disease (id BIGINT AUTO_INCREMENT PRIMARY KEY, icd_code VARCHAR(30) UNIQUE, disease_name VARCHAR(120) NOT NULL);
CREATE TABLE medical_record_disease (medical_record_id BIGINT NOT NULL, disease_id BIGINT NOT NULL, PRIMARY KEY (medical_record_id,disease_id));
CREATE TABLE medical_technology (id BIGINT AUTO_INCREMENT PRIMARY KEY, project_code VARCHAR(32) NOT NULL UNIQUE, project_name VARCHAR(120) NOT NULL, project_type VARCHAR(16) NOT NULL, unit_price DECIMAL(10,2) NOT NULL, specification VARCHAR(120) DEFAULT '', enabled TINYINT NOT NULL DEFAULT 1);
CREATE TABLE check_request (id BIGINT AUTO_INCREMENT PRIMARY KEY, register_id BIGINT NOT NULL, medical_technology_id BIGINT NOT NULL, check_info VARCHAR(512), check_position VARCHAR(255), creation_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, check_employee_id BIGINT, inputcheck_employee_id BIGINT, check_time TIMESTAMP NULL, check_result TEXT, client_request_id VARCHAR(80) UNIQUE, check_state VARCHAR(24) NOT NULL DEFAULT 'CREATED', check_remark VARCHAR(512));
CREATE TABLE inspection_request (id BIGINT AUTO_INCREMENT PRIMARY KEY, register_id BIGINT NOT NULL, medical_technology_id BIGINT NOT NULL, inspection_info VARCHAR(512), inspection_position VARCHAR(255), creation_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, inspection_employee_id BIGINT, inputinspection_employee_id BIGINT, inspection_time TIMESTAMP NULL, inspection_result TEXT, client_request_id VARCHAR(80) UNIQUE, inspection_state VARCHAR(24) NOT NULL DEFAULT 'CREATED', inspection_remark VARCHAR(512));
CREATE TABLE disposal_request (id BIGINT AUTO_INCREMENT PRIMARY KEY, register_id BIGINT NOT NULL, medical_technology_id BIGINT NOT NULL, disposal_info VARCHAR(512), disposal_position VARCHAR(255), creation_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, disposal_employee_id BIGINT, inputdisposal_employee_id BIGINT, disposal_time TIMESTAMP NULL, disposal_result TEXT, client_request_id VARCHAR(80) UNIQUE, disposal_state VARCHAR(24) NOT NULL DEFAULT 'CREATED', disposal_remark VARCHAR(512));
CREATE TABLE drug_info (id BIGINT AUTO_INCREMENT PRIMARY KEY, drug_code VARCHAR(32) NOT NULL UNIQUE, drug_name VARCHAR(120) NOT NULL, unit VARCHAR(30) NOT NULL DEFAULT '盒', producer VARCHAR(120), drug_type VARCHAR(40), unit_price DECIMAL(10,2) NOT NULL, stock INT NOT NULL DEFAULT 0, enabled TINYINT NOT NULL DEFAULT 1);
CREATE TABLE prescription (id BIGINT AUTO_INCREMENT PRIMARY KEY, client_request_id VARCHAR(80) UNIQUE, register_id BIGINT NOT NULL, employee_id BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE prescription_item (id BIGINT AUTO_INCREMENT PRIMARY KEY, prescription_id BIGINT NOT NULL, drug_id BIGINT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, dosage VARCHAR(100) NOT NULL, frequency VARCHAR(100) NOT NULL, use_days INT NOT NULL, advice VARCHAR(255), status VARCHAR(16) NOT NULL DEFAULT 'UNPAID', CONSTRAINT fk_pi_pres FOREIGN KEY(prescription_id) REFERENCES prescription(id));
CREATE TABLE charge_item (id BIGINT AUTO_INCREMENT PRIMARY KEY, register_id BIGINT NOT NULL, category VARCHAR(16) NOT NULL, ref_id BIGINT NOT NULL, description VARCHAR(160) NOT NULL, amount DECIMAL(10,2) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'UNPAID', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, paid_at TIMESTAMP NULL, UNIQUE KEY uk_charge_ref(category,ref_id), INDEX idx_charge_reg(register_id,status));
CREATE TABLE charge_transaction (id BIGINT AUTO_INCREMENT PRIMARY KEY, item_id BIGINT NOT NULL, direction VARCHAR(10) NOT NULL, amount DECIMAL(10,2) NOT NULL, received_amount DECIMAL(10,2), change_amount DECIMAL(10,2), method VARCHAR(30) NOT NULL, operator_id BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_tx_item(item_id));
CREATE TABLE drug_stock_transaction (id BIGINT AUTO_INCREMENT PRIMARY KEY, drug_id BIGINT NOT NULL, delta INT NOT NULL, reason VARCHAR(30) NOT NULL, ref_id BIGINT, operator_id BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auth_session (id BIGINT AUTO_INCREMENT PRIMARY KEY, employee_id BIGINT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT NULL, action VARCHAR(80) NOT NULL, target VARCHAR(120) NOT NULL, detail VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_at(created_at));
